import "server-only";
import { createHash } from "crypto";
import { db } from "./db";
import { clip, generateJson, isAiEnabled } from "./ai";

/**
 * Quizzes and practice challenges, generated by AI from a lesson's written text only
 * (the AI can't watch the video) and cached once per lesson for every student.
 */

export const MIN_SOURCE_CHARS = 400;
export const MIN_QUESTIONS = 3;
const MAX_QUESTIONS = 8;
const MAX_SOURCE_CHARS_SENT = 30_000;
const FAILURE_COOLDOWN_MS = 60_000;

export type Question = { id: string; question: string; options: string[]; correctIndex: number; explanation: string; sourceQuote: string };
export type Challenge = { id: string; title: string; instructions: string; checklist: string[] };
/** What the browser gets before answering: no correct answers, explanations or quotes. */
export type PublicQuestion = { id: string; question: string; options: string[] };

export type AssessmentState =
  | { status: "ready"; questions: Question[]; challenges: Challenge[] }
  | { status: "too_short" } // not enough lesson text to ground a quiz
  | { status: "unavailable" }; // AI off or generation failed

type LessonText = { content: string; transcript: string };

export function sourceText(lesson: LessonText) {
  return [lesson.content, lesson.transcript].map((s) => s.trim()).filter(Boolean).join("\n\n");
}

export const hashOf = (s: string) => createHash("sha256").update(s).digest("hex");
const shortHash = (s: string) => createHash("sha1").update(s).digest("hex").slice(0, 10);

/** Lowercase, straight quotes, no markdown emphasis, single spaces — for quote matching. */
export function normalizeForMatch(s: string) {
  return s
    .toLowerCase()
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[–—]/g, "-")
    .replace(/[*_`#>]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function parseStored(row: { questionsJson: string; challengesJson: string }) {
  try {
    return { questions: JSON.parse(row.questionsJson) as Question[], challenges: JSON.parse(row.challengesJson) as Challenge[] };
  } catch {
    return { questions: [], challenges: [] };
  }
}

/* ----------------------------- Generation ----------------------------- */

const SYSTEM = `You write multiple-choice quiz questions and practice challenges for lessons in a trading education course.
Use ONLY facts stated in the lesson source text you are given. Never invent trading rules, numbers, indicators or strategies that are not in the text. Never give buy/sell signals or advice to place real trades.

Questions:
- Write 5 to 8 questions that check understanding of the most important ideas in the text.
- Each has exactly 4 options and exactly one correct option (correctIndex is 0-3). Wrong options must be plausible but clearly wrong according to the text.
- "explanation": one or two sentences on why the correct option is right.
- "sourceQuote": one sentence copied EXACTLY, character for character, from the source text that supports the correct answer.

Challenges:
- Write 1 to 3 practical challenges the student completes on their own by writing a text answer (no uploads), e.g. explaining the lesson's entry conditions in their own words, or describing where they would mark a level on a chart and why.
- Only mention a video timestamp if that timestamp appears in the source text.
- "checklist": 3 to 5 short self-check items the student ticks when their answer covers them.`;

const SCHEMA = {
  type: "object",
  properties: {
    questions: {
      type: "array",
      items: {
        type: "object",
        properties: {
          question: { type: "string" },
          options: { type: "array", items: { type: "string" } },
          correctIndex: { type: "integer" },
          explanation: { type: "string" },
          sourceQuote: { type: "string" },
        },
        required: ["question", "options", "correctIndex", "explanation", "sourceQuote"],
        additionalProperties: false,
      },
    },
    challenges: {
      type: "array",
      items: {
        type: "object",
        properties: {
          title: { type: "string" },
          instructions: { type: "string" },
          checklist: { type: "array", items: { type: "string" } },
        },
        required: ["title", "instructions", "checklist"],
        additionalProperties: false,
      },
    },
  },
  required: ["questions", "challenges"],
  additionalProperties: false,
};

const isStr = (v: unknown): v is string => typeof v === "string" && v.trim().length > 0;

/** Validate the model's JSON and keep only questions whose quote really appears in the source. */
export function validateGenerated(raw: unknown, source: string): { questions: Question[]; challenges: Challenge[] } | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as { questions?: unknown; challenges?: unknown };
  const haystack = normalizeForMatch(source);
  const seen = new Set<string>();

  const questions: Question[] = [];
  for (const q of Array.isArray(r.questions) ? r.questions : []) {
    if (!q || typeof q !== "object") continue;
    const { question, options, correctIndex, explanation, sourceQuote } = q as Record<string, unknown>;
    if (!isStr(question) || !isStr(explanation) || !isStr(sourceQuote)) continue;
    if (!Array.isArray(options) || options.length !== 4 || !options.every(isStr)) continue;
    if (new Set(options.map((o) => normalizeForMatch(o))).size !== 4) continue;
    if (typeof correctIndex !== "number" || !Number.isInteger(correctIndex) || correctIndex < 0 || correctIndex > 3) continue;
    const quote = normalizeForMatch(sourceQuote);
    if (quote.length < 15 || !haystack.includes(quote)) continue; // grounding check
    const id = `q_${shortHash(normalizeForMatch(question))}`;
    if (seen.has(id)) continue;
    seen.add(id);
    questions.push({
      id,
      question: clip(question, 400),
      options: options.map((o) => clip(o, 200)),
      correctIndex,
      explanation: clip(explanation, 600),
      sourceQuote: sourceQuote.trim(),
    });
    if (questions.length === MAX_QUESTIONS) break;
  }

  const challenges: Challenge[] = [];
  for (const c of Array.isArray(r.challenges) ? r.challenges : []) {
    if (!c || typeof c !== "object") continue;
    const { title, instructions, checklist } = c as Record<string, unknown>;
    if (!isStr(title) || !isStr(instructions) || !Array.isArray(checklist)) continue;
    const items = checklist.filter(isStr).map((i) => clip(i, 200)).slice(0, 5);
    if (items.length < 3) continue;
    const id = `c_${shortHash(normalizeForMatch(title))}`;
    if (challenges.some((x) => x.id === id)) continue;
    challenges.push({ id, title: clip(title, 120), instructions: clip(instructions, 1200), checklist: items });
    if (challenges.length === 3) break;
  }

  if (questions.length === 0 && challenges.length === 0) return null;
  return { questions, challenges };
}

async function generate(source: string) {
  const prompt = `<lesson_source>\n${source.slice(0, MAX_SOURCE_CHARS_SENT)}\n</lesson_source>\n\nWrite the quiz questions and practice challenges for this lesson.`;
  const raw = await generateJson({ system: SYSTEM, prompt, schema: SCHEMA, maxTokens: 8000, effort: "low" });
  return validateGenerated(raw, source);
}

// One generation per lesson at a time within this server process, plus a short
// cooldown after a failure so a broken API doesn't get hammered by every page view.
const inFlight = new Map<string, Promise<AssessmentState>>();
const lastFailure = new Map<string, number>();

async function generateAndStore(lessonId: string, source: string, hash: string): Promise<AssessmentState> {
  const failedAt = lastFailure.get(lessonId);
  if (failedAt && Date.now() - failedAt < FAILURE_COOLDOWN_MS) return { status: "unavailable" };

  const result = await generate(source);
  if (!result) {
    lastFailure.set(lessonId, Date.now());
    return { status: "unavailable" };
  }
  const data = {
    questionsJson: JSON.stringify(result.questions),
    challengesJson: JSON.stringify(result.challenges),
    sourceHash: hash,
    source: "AI",
    generatedAt: new Date(),
  };
  try {
    await db.lessonAssessment.upsert({ where: { lessonId }, create: { lessonId, ...data }, update: data });
  } catch {
    // Another server instance created it at the same moment — use theirs.
    const row = await db.lessonAssessment.findUnique({ where: { lessonId } });
    if (row) return { status: "ready", ...parseStored(row) };
    return { status: "unavailable" };
  }
  return { status: "ready", ...result };
}

/**
 * The lesson's quiz + challenges. Uses the cache when it matches the current lesson text;
 * otherwise generates (only if `generate` is true and AI is enabled).
 */
export async function getAssessment(lessonId: string, { generate: allowGenerate }: { generate: boolean }): Promise<AssessmentState> {
  const lesson = await db.lesson.findUnique({ where: { id: lessonId }, select: { content: true, transcript: true } });
  if (!lesson) return { status: "unavailable" };
  const source = sourceText(lesson);
  if (source.length < MIN_SOURCE_CHARS) return { status: "too_short" };
  const hash = hashOf(source);

  const cached = await db.lessonAssessment.findUnique({ where: { lessonId } });
  if (cached && cached.sourceHash === hash) return { status: "ready", ...parseStored(cached) };
  if (!allowGenerate || !isAiEnabled()) return { status: "unavailable" };

  const key = `${lessonId}:${hash}`;
  let job = inFlight.get(key);
  if (!job) {
    job = generateAndStore(lessonId, source, hash).finally(() => inFlight.delete(key));
    inFlight.set(key, job);
  }
  return job;
}

/** Admin "Regenerate": ignore the cache and the failure cooldown. */
export async function regenerateAssessment(lessonId: string): Promise<AssessmentState> {
  const lesson = await db.lesson.findUnique({ where: { id: lessonId }, select: { content: true, transcript: true } });
  if (!lesson) return { status: "unavailable" };
  const source = sourceText(lesson);
  if (source.length < MIN_SOURCE_CHARS) return { status: "too_short" };
  lastFailure.delete(lessonId);
  return generateAndStore(lessonId, source, hashOf(source));
}

/**
 * Should the lesson page show the Quiz / Practice section, and in which state?
 * Cheap: no AI call. With AI off, only a cache that matches the current text is shown.
 */
export async function practiceAvailability(lesson: { id: string } & LessonText): Promise<"available" | "too_short" | "hidden"> {
  const source = sourceText(lesson);
  if (!isAiEnabled()) {
    if (source.length < MIN_SOURCE_CHARS) return "hidden";
    const cached = await db.lessonAssessment.findUnique({ where: { lessonId: lesson.id }, select: { sourceHash: true } });
    return cached?.sourceHash === hashOf(source) ? "available" : "hidden";
  }
  return source.length < MIN_SOURCE_CHARS ? "too_short" : "available";
}

export function toPublic(q: Question): PublicQuestion {
  return { id: q.id, question: q.question, options: q.options };
}

/** Read a cached assessment as-is (admin preview), with whether it's stale. */
export async function cachedAssessment(lessonId: string) {
  const [lesson, row] = await Promise.all([
    db.lesson.findUnique({ where: { id: lessonId }, select: { content: true, transcript: true } }),
    db.lessonAssessment.findUnique({ where: { lessonId } }),
  ]);
  if (!lesson) return null;
  const source = sourceText(lesson);
  return {
    sourceChars: source.length,
    row: row ? { ...parseStored(row), generatedAt: row.generatedAt, stale: row.sourceHash !== hashOf(source) } : null,
  };
}
